<?php declare(strict_types=1); ?>
<section class="panel"><header class="panel-head"><div><span class="eyebrow">Human review boundary</span><h2>Staged supplier submissions</h2><p>Accepting a PO response or ASN updates canonical fulfillment evidence. Accepting an invoice converts it into Section 18 for three-way matching. Other records remain portal evidence.</p></div></header><div class="portal-queue"><?php $queues=[['po_response',$poResponses,'response_number','notes'],['asn',$asns,'asn_number','tracking_number'],['invoice',$invoices,'invoice_number','document_reference'],['document',$documents,'title','document_reference'],['sourcing',$sourcing,'title','document_reference'],['quality',$quality,'response_number','evidence_reference']];foreach($queues as [$kind,$rows,$titleField,$detailField])foreach($rows as $record): ?><article class="portal-record"><header><div><span class="eyebrow"><?= h(status_label($kind)) ?></span><strong><?= h((string)$record[$titleField]) ?></strong><small><?= h((string)($record[$detailField]??'')) ?> · Submitted <?= h(date_us($record['created_at'],true)) ?></small></div><?= badge($record['status']) ?></header><?php if(can('supplier_portal.review')&&in_array($record['status'],['submitted','changes_requested'],true)): ?><form class="form-grid" method="post" action="<?= h(app_url('supplier-portal-action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="review_record"><input type="hidden" name="record_type" value="<?= h($kind) ?>"><input type="hidden" name="record_id" value="<?= (int)$record['id'] ?>"><input type="hidden" name="supplier_id" value="<?= $selectedSupplierId ?>"><label><span>Decision</span><select name="decision"><option value="accepted">Accept</option><option value="changes_requested">Request changes</option><option value="rejected">Reject</option></select></label><label class="span-2"><span>Review evidence</span><textarea name="review_note" required></textarea></label><div class="span-2"><button class="button primary">Complete review</button></div></form><?php endif; ?></article><?php endforeach; ?></div></section>
